package com.zlearn.network

import retrofit2.http.Body
import retrofit2.http.Headers
import retrofit2.http.POST
import retrofit2.Response

// 阿里云大模型对话请求体
// 你需要根据实际API文档调整字段
// 这里只做通用示例

data class AliyunChatRequest(
    val model: String, // 如 qwen-turbo
    val input: Input
)
data class Input(
    val messages: List<Message>
)
data class Message(
    val role: String, // "user" or "assistant"
    val content: String
)
data class AliyunChatResponse(
    val code: String?,
    val output: Output?
)
data class Output(
    val text: String?
)

interface AiApiService {
    @Headers("Content-Type: application/json")
    @POST("/api/v1/services/aigc/text-generation/generation") // 阿里云Qwen对话API路径
    suspend fun chat(@Body request: AliyunChatRequest): Response<AliyunChatResponse>
}

package com.zlearn.network

import retrofit2.http.Body
import retrofit2.http.Headers
import retrofit2.http.POST
import retrofit2.Response
import retrofit2.http.Streaming

// 阿里云大模型对话请求体
// 你需要根据实际API文档调整字段
// 这里只做通用示例

data class AliyunChatRequest(
    val model: String, // 如 qwen-turbo
    val input: Input
)
data class Input(
    val messages: List<Message>
)
data class Message(
    val role: String, // "user" or "assistant"
    val content: String
)
data class AliyunChatResponse(
    val code: String?,
    val output: Output?
)
data class Output(
    val text: String?
)

interface AiApiService {
    @Headers("Content-Type: application/json")
    @POST("/api/v1/services/aigc/text-generation/generation") // 阿里云Qwen对话API路径
    suspend fun chat(@Body request: AliyunChatRequest): Response<AliyunChatResponse>

    @Headers("Content-Type: application/json")
    @POST("/api/v1/services/aigc/text-generation/generation")
    @Streaming
    suspend fun chatStream(@Body request: AliyunChatRequest): okhttp3.ResponseBody
}

// AiInputBar.kt
package com.zlearn.ui.components

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp

/**
 * AI 输入栏组件（输入框 + 发送按钮）
 * 封装了流光边框输入框和发送按钮的布局
 *
 * @param input 输入框当前值
 * @param onInputChange 输入变化回调
 * @param onSend 发送回调
 * @param isLoading 是否正在加载（显示加载按钮）
 * @param modifier 外部修饰符
 * @param placeholder 占位文字
 * @param buttonText 按钮文字
 */
@Composable
fun AiInputBar(
    input: String,
    onInputChange: (String) -> Unit,
    onSend: () -> Unit,
    isLoading: Boolean = false,
    modifier: Modifier = Modifier,
    placeholder: String = "向大模型提问...",
    buttonText: String = "发送"
) {
    Row(
        verticalAlignment = Alignment.CenterVertically,
        modifier = modifier.fillMaxWidth()
    ) {
        // 流光边框输入框
        FlowingBorderTextField(
            value = input,
            onValueChange = onInputChange,
            label = "", // 不用label，防止label动画导致输入框高度变化
            modifier = Modifier.weight(1f).padding(end = 8.dp),
            isActive = input.isNotEmpty() && !isLoading, // 仅在未加载时流光
            enabled = !isLoading, // 禁用输入
            placeholder = placeholder // 用placeholder代替label
        )

        // 发送按钮
        Button(
            onClick = { if (!isLoading) onSend() }, // 防止重复点击
            enabled = input.isNotBlank() && !isLoading,
            shape = RoundedCornerShape(28.dp),
            modifier = Modifier.height(56.dp)
        ) {
            if (isLoading) {
                CircularProgressIndicator(
                    modifier = Modifier.size(20.dp),
                    strokeWidth = 2.dp,
                    color = MaterialTheme.colorScheme.onPrimary
                )
            } else {
                Text(buttonText)
            }
        }
    }
}

