import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp

/**
 * AI 输入栏组件（输入框 + 发送按钮）
 * 封装了流光边框输入框和发送按钮的布局
 *
 * @param input 输入框当前值
 * @param onInputChange 输入变化回调
 * @param onSend 发送回调
 * @param isLoading 是否正在加载（显示加载按钮）
 * @param modifier 外部修饰符
 * @param placeholder 占位文字
 * @param buttonText 按钮文字
 */
@Composable
fun AiInputBar(
    input: String,
    onInputChange: (String) -> Unit,
    onSend: () -> Unit,
    isLoading: Boolean = false,
    modifier: Modifier = Modifier,
    placeholder: String = "向大模型提问...",
    buttonText: String = "发送"
) {
    Row(
        verticalAlignment = Alignment.CenterVertically,
        modifier = modifier.fillMaxWidth()
    ) {
        // 流光边框输入框
        FlowingBorderTextField(
            value = input,
            onValueChange = onInputChange,
            label = "", // 不用label，防止label动画导致输入框高度变化
            modifier = Modifier.weight(1f).padding(end = 8.dp),
            isActive = !isLoading, // 只根据加载状态决定流光，输入内容不影响
            enabled = !isLoading, // 禁用输入
            placeholder = placeholder // 用placeholder代替label
        )

        // 发送按钮
        Button(
            onClick = { if (!isLoading) onSend() }, // 防止重复点击
            enabled = input.isNotBlank() && !isLoading,
            shape = RoundedCornerShape(28.dp),
            modifier = Modifier.height(56.dp)
        ) {
            if (isLoading) {
                CircularProgressIndicator(
                    modifier = Modifier.size(20.dp),
                    strokeWidth = 2.dp,
                    color = MaterialTheme.colorScheme.onPrimary
                )
            } else {
                Text(buttonText)
            }
        }
    }
}

package com.zlearn.utils

import android.Manifest
import android.bluetooth.*
import android.bluetooth.le.*
import android.content.Context
import android.content.pm.PackageManager
import android.os.Build
import android.os.ParcelUuid
import java.util.*

object BleShareTransport {

    private const val SERVICE_UUID_STRING = "12345678-1234-1234-1234-123456789abc"
    private const val CHARACTERISTIC_UUID_STRING = "87654321-4321-4321-4321-cba987654321"

    private val SERVICE_UUID = UUID.fromString(SERVICE_UUID_STRING)
    private val CHARACTERISTIC_UUID = UUID.fromString(CHARACTERISTIC_UUID_STRING)

    private lateinit var context: Context
    private lateinit var bluetoothManager: BluetoothManager
    private lateinit var bluetoothAdapter: BluetoothAdapter

    private var gattServer: BluetoothGattServer? = null
    private var advertiser: BluetoothLeAdvertiser? = null
    private var scanner: BluetoothLeScanner? = null
    private var currentGatt: BluetoothGatt? = null

    private var onDataReceived: ((String) -> Unit)? = null

    fun init(ctx: Context) {
        context = ctx
        bluetoothManager = ctx.getSystemService(Context.BLUETOOTH_SERVICE) as BluetoothManager
        bluetoothAdapter = bluetoothManager.adapter
    }

    private fun hasPermission(permission: String): Boolean {
        return context.checkSelfPermission(permission) == PackageManager.PERMISSION_GRANTED
    }

    // 发送端：开始广播并提供数据
    fun startAdvertising(data: String) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            if (!hasPermission(Manifest.permission.BLUETOOTH_ADVERTISE) ||
                !hasPermission(Manifest.permission.BLUETOOTH_CONNECT)) {
                // Permissions not granted, cannot advertise
                return
            }
        }
        // 创建服务
        val service = BluetoothGattService(SERVICE_UUID, BluetoothGattService.SERVICE_TYPE_PRIMARY)
        val characteristic = BluetoothGattCharacteristic(
            CHARACTERISTIC_UUID,
            BluetoothGattCharacteristic.PROPERTY_READ,
            BluetoothGattCharacteristic.PERMISSION_READ
        )
        characteristic.value = data.toByteArray(Charsets.UTF_8)
        service.addCharacteristic(characteristic)

        gattServer = bluetoothManager.openGattServer(context, object : BluetoothGattServerCallback() {
            override fun onCharacteristicReadRequest(
                device: BluetoothDevice,
                requestId: Int,
                offset: Int,
                characteristic: BluetoothGattCharacteristic
            ) {
                gattServer?.sendResponse(device, requestId, BluetoothGatt.GATT_SUCCESS, offset, characteristic.value)
            }
        })
        gattServer?.addService(service)

        // 开始广播
        advertiser = bluetoothAdapter.bluetoothLeAdvertiser
        val advertiseSettings = AdvertiseSettings.Builder()
            .setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_LATENCY)
            .setTxPowerLevel(AdvertiseSettings.ADVERTISE_TX_POWER_HIGH)
            .setConnectable(true)
            .build()
        val advertiseData = AdvertiseData.Builder()
            .setIncludeDeviceName(true)
            .addServiceUuid(ParcelUuid(SERVICE_UUID))
            .build()
        advertiser?.startAdvertising(advertiseSettings, advertiseData, object : AdvertiseCallback() {})
    }

    fun stopAdvertising() {
        advertiser?.stopAdvertising(object : AdvertiseCallback() {})
        gattServer?.close()
        gattServer = null
    }

    // 接收端：扫描并接收数据
    fun startScanning(onReceived: (String) -> Unit) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            if (!hasPermission(Manifest.permission.BLUETOOTH_SCAN) ||
                !hasPermission(Manifest.permission.BLUETOOTH_CONNECT)) {
                // Permissions not granted, cannot scan
                return
            }
        }
        onDataReceived = onReceived
        scanner = bluetoothAdapter.bluetoothLeScanner
        val scanSettings = ScanSettings.Builder()
            .setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY)
            .build()
        val scanFilter = ScanFilter.Builder()
            .setServiceUuid(ParcelUuid(SERVICE_UUID))
            .build()
        scanner?.startScan(listOf(scanFilter), scanSettings, object : ScanCallback() {
            override fun onScanResult(callbackType: Int, result: ScanResult) {
                val device = result.device
                currentGatt = device.connectGatt(context, false, object : BluetoothGattCallback() {
                    override fun onConnectionStateChange(gatt: BluetoothGatt, status: Int, newState: Int) {
                        if (newState == BluetoothProfile.STATE_CONNECTED) {
                            gatt.requestMtu(512) // 请求更大MTU
                            gatt.discoverServices()
                        }
                    }

                    override fun onMtuChanged(gatt: BluetoothGatt, mtu: Int, status: Int) {
                        // MTU changed
                    }

                    override fun onServicesDiscovered(gatt: BluetoothGatt, status: Int) {
                        val service = gatt.getService(SERVICE_UUID)
                        val characteristic = service?.getCharacteristic(CHARACTERISTIC_UUID)
                        gatt.readCharacteristic(characteristic)
                    }

                    override fun onCharacteristicRead(gatt: BluetoothGatt, characteristic: BluetoothGattCharacteristic, status: Int) {
                        val data = String(characteristic.value, Charsets.UTF_8)
                        onDataReceived?.invoke(data)
                        gatt.close()
                        stopScanning()
                    }
                })
            }
        })
    }

    fun stopScanning() {
        scanner?.stopScan(object : ScanCallback() {})
        currentGatt?.close()
        currentGatt = null
    }
}

