package com.zlearn

import android.app.Application
import android.content.SharedPreferences
import com.zlearn.utils.AppMode
import com.zlearn.utils.BleShareTransport
import dagger.hilt.android.HiltAndroidApp
import kotlinx.coroutines.*
import okhttp3.*
import android.os.Process
import java.io.IOException

@HiltAndroidApp
class MyApplication : Application() {

    private lateinit var sharedPreferences: SharedPreferences
    private val scope = CoroutineScope(Dispatchers.IO + SupervisorJob())
    private val client = OkHttpClient()

    // 手动设置应用模式：DEV（开发）、PRE（预发布）、REL（发布）
    private val appMode = AppMode.DEV  // 更改此值以切换模式

    override fun onCreate() {
        super.onCreate()
        BleShareTransport.init(this)

        sharedPreferences = getSharedPreferences("app_prefs", MODE_PRIVATE)
        val modeString = sharedPreferences.getString("app_mode", "DEV") ?: "DEV"
        val mode = try {
            AppMode.valueOf(modeString)
        } catch (_: IllegalArgumentException) {
            AppMode.DEV
        }

        if (mode == AppMode.PRE) {
            startHeartbeat()
        }
    }

    private fun startHeartbeat() {
        scope.launch {
            while (isActive) {
                try {
                    val request = Request.Builder()
                        .url("http://10.0.2.2:8080/api/heartbeat")
                        .build()
                    val response = client.newCall(request).execute()
                    if (!response.isSuccessful) {
                        throw IOException("Unexpected code $response")
                    }
                } catch (e: IOException) {
                    // Heartbeat failed, crash the app
                    Process.killProcess(Process.myPid())
                }
                delay(30000L)
            }
        }
    }

    fun setAppMode(mode: AppMode) {
        sharedPreferences.edit().putString("app_mode", mode.name).apply()
    }

    fun getAppMode(): AppMode {
        val modeString = sharedPreferences.getString("app_mode", "DEV") ?: "DEV"
        return try {
            AppMode.valueOf(modeString)
        } catch (_: IllegalArgumentException) {
            AppMode.DEV
        }
    }
}

