import com.zlearn.ocr.OcrUtil
import kotlinx.coroutines.launch

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun QuestionListScreen(
    modifier: Modifier = Modifier,
    viewModel: QuestionViewModel = hiltViewModel(),
    navController: NavController
) {
    val questions by viewModel.questions.collectAsState()
    val aiStreamResponse by viewModel.aiStreamResponse.collectAsState()
    var summaryResponse by remember { mutableStateOf("") }
    var summaryLoading by remember { mutableStateOf(false) }
    var aiInput by remember { mutableStateOf("") }
    var isStreaming by remember { mutableStateOf(false) }
    var showAddDialog by remember { mutableStateOf(false) }
    var newOcrText by remember { mutableStateOf("") }
    var newSubject by remember { mutableStateOf("") }
    var newDifficulty by remember { mutableStateOf(3) }
    var newAiAnalysis by remember { mutableStateOf("") }
    var newSummary by remember { mutableStateOf("") }
    var newImagePath by remember { mutableStateOf("") }
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    var ocrImageUri by remember { mutableStateOf<Uri?>(null) }
    var ocrLoading by remember { mutableStateOf(false) }
    val pickImageLauncher = rememberLauncherForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        ocrImageUri = uri
        if (uri != null) {
            ocrLoading = true
            coroutineScope.launch {
                val ocrResult = OcrUtil.recognizeTextFromUri(context, uri)
                ocrLoading = false
                if (ocrResult != null) {
                    newOcrText = ocrResult
                    // OCR后自动生成summary（独立调用AI）
                    summaryLoading = true
                    summaryResponse = ""
                    coroutineScope.launch {
                        val summary = viewModel.generateSummary(ocrResult)
                        summaryResponse = summary
                        newSummary = if (summary.length > 20) summary.take(20) else summary
                        summaryLoading = false
                    }
                    // 识别成功反馈
                    android.widget.Toast.makeText(context, "识别成功", android.widget.Toast.LENGTH_SHORT).show()
                } else {
                    android.widget.Toast.makeText(context, "识别失败，请重试", android.widget.Toast.LENGTH_SHORT).show()
                }
            }
        }
    }
    var showActionSheet by remember { mutableStateOf(false) }
    var selectedQuestion: QuestionEntity? by remember { mutableStateOf(null) }
    Scaffold(
        floatingActionButton = {
            FloatingActionButton(onClick = { showAddDialog = true }) {
                Text("+")
            }
        }
    ) { innerPadding ->
        Column(modifier = modifier.padding(innerPadding).fillMaxSize()) {
            // --- AI对话区（流式输出）已整体注释 ---
            /*
            OutlinedTextField(
                value = aiInput,
                onValueChange = { aiInput = it },
                label = { Text("和大模型对话... (流式)") },
                modifier = Modifier.fillMaxWidth().padding(8.dp),
                enabled = !isStreaming
            )
            Button(
                onClick = {
                    viewModel.clearAiStreamResponse()
                    isStreaming = true
                    coroutineScope.launch {
                        viewModel.chatWithAiStream(aiInput)
                        isStreaming = false
                    }
                },
                enabled = aiInput.isNotBlank() && !isStreaming
            ) {
                Text(if (isStreaming) "AI生成中..." else "发送到AI")
            }
            if (aiStreamResponse.isNotBlank()) {
                Text("AI回复：$aiStreamResponse", modifier = Modifier.padding(8.dp), color = MaterialTheme.colorScheme.primary)
            }
            Divider(modifier = Modifier.padding(vertical = 8.dp))
            */
            // --- 题目列表 ---
            LazyColumn(modifier = Modifier.fillMaxSize()) {
                items(questions.size) { index ->
                    val q = questions[index]
                    QuestionCard(
                        summary = if (q.summary.isNotBlank()) q.summary else q.ocrText.take(20),
                        onClick = {
                            println("[DEBUG] Card clicked, id=${q.id}")
                            navController.navigate("question_detail/${q.id}")
                        },
                        onLongPress = {
                            selectedQuestion = q
                            showActionSheet = true
                        }
                    )
                }
            }
        }
        if (showAddDialog) {
            AlertDialog(
                onDismissRequest = { showAddDialog = false },
                title = { Text("添加题目") },
                text = {
                    Column {
                        OutlinedTextField(
                            value = newOcrText,
                            onValueChange = { newOcrText = it },
                            label = { Text("题干/OCR文本") },
                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)
                        )
                        OutlinedTextField(
                            value = newSubject,
                            onValueChange = { newSubject = it },
                            label = { Text("学科") },
                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)
                        )
                        OutlinedTextField(
                            value = newAiAnalysis,
                            onValueChange = { newAiAnalysis = it },
                            label = { Text("AI解析(可选)") },
                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)
                        )
                         OutlinedTextField(
                             value = newImagePath,
                             onValueChange = { newImagePath = it },
                             label = { Text("图片路径(可选)") },
                             modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)
                         )
                        // summary只读或隐藏，若需显示可用只读框
                        OutlinedTextField(
                            value = newSummary,
                            onValueChange = {},
                            label = { Text("AI摘要(自动生成)") },
                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                            enabled = false,
                            readOnly = true
                        )
                        if (summaryLoading) {
                            Text("正在生成摘要...", color = MaterialTheme.colorScheme.primary, modifier = Modifier.padding(4.dp))
                        }
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text("难度:")
                            Slider(
                                value = newDifficulty.toFloat(),
                                onValueChange = { newDifficulty = it.toInt() },
                                valueRange = 1f..5f,
                                steps = 3,
                                modifier = Modifier.weight(1f)
                            )
                            Text(newDifficulty.toString())
                        }
                        // 新增：OCR图片选择与识别按钮
                        Row(verticalAlignment = Alignment.CenterVertically) {
                                    Button(onClick = {
                                        pickImageLauncher.launch("image/*")
                                    }, enabled = !ocrLoading) {
                                        Text("选择图片/拍照")
                                    }
                                    Spacer(modifier = Modifier.width(8.dp))
                                    if (ocrLoading) {
                                        CircularProgressIndicator(modifier = Modifier.size(20.dp))
                                    } else if (ocrImageUri != null) {
                                        Text("已选择图片")
                                    }
                        }
                    }
                },
                confirmButton = {
                    TextButton(onClick = {
                        if (newOcrText.isNotBlank()) {
                            viewModel.addQuestion(
                                QuestionEntity(
                                    imagePath = newImagePath,
                                    ocrText = newOcrText,
                                    aiAnalysis = newAiAnalysis,
                                    summary = newSummary,
                                    subject = newSubject,
                                    difficulty = newDifficulty,
                                    createTime = System.currentTimeMillis(),
                                    isArchived = false
                                )
                            )
                            showAddDialog = false
                            newOcrText = ""
                            newSubject = ""
                            newAiAnalysis = ""
                            newSummary = ""
                            newImagePath = ""
                            newDifficulty = 3
                        }
                    }) { Text("添加") }
                },
                dismissButton = {
                    TextButton(onClick = { showAddDialog = false }) { Text("取消") }
                }
            )
        }
        if (showActionSheet && selectedQuestion != null) {
            ModalBottomSheet(onDismissRequest = { showActionSheet = false }) {
                Column(Modifier.padding(16.dp)) {
                    TextButton(onClick = {
                        viewModel.deleteQuestion(selectedQuestion!!)
                        showActionSheet = false
                    }) { Text("删除", color = MaterialTheme.colorScheme.error) }
                    TextButton(onClick = {
                        viewModel.archiveQuestion(selectedQuestion!!.id)
                        showActionSheet = false
                    }) { Text("归档") }
                    TextButton(onClick = { showActionSheet = false }) { Text("取消") }
                }
            }
        }
    }

}

package com.zlearn.data.repository
import com.zlearn.data.database.QuestionDao import com.zlearn.data.database.QuestionEntity import com.zlearn.data.remote.ApiService import com.zlearn.data.remote.SyncQuestionDto import com.zlearn.data.remote.SyncQuestionsRequest import com.zlearn.network.AiApiService import com.zlearn.network.AliyunChatRequest import com.zlearn.network.AliyunChatResponse import retrofit2.Response import javax.inject.Inject
class QuestionRepository @Inject constructor( private val questionDao: QuestionDao, private val apiService: ApiService, private val aiApiService: AiApiService ) { suspend fun insert(question: QuestionEntity) = questionDao.insert(question) suspend fun getAll(): List<QuestionEntity> = questionDao.getAll() suspend fun getById(id: Int): QuestionEntity? = questionDao.getById(id) suspend fun update(question: QuestionEntity) = questionDao.update(question) suspend fun delete(question: QuestionEntity) { val now = System.currentTimeMillis() questionDao.softDeleteById(question.id, deletedAt = now, updatedAt = now) } suspend fun archive(id: Int) = questionDao.archive(id, System.currentTimeMillis()) suspend fun archive(id: Int, archiveType: String) = questionDao.archive(id, archiveType, System.currentTimeMillis())
suspend fun unarchive(id: Int) = questionDao.unarchive(id, System.currentTimeMillis()) suspend fun getActive(): List<QuestionEntity> = questionDao.getActive() suspend fun getArchived(): List<QuestionEntity> = questionDao.getArchived() suspend fun getAllArchiveTypes(): List<String> = questionDao.getAllArchiveTypes() suspend fun getByArchiveType(type: String): List<QuestionEntity> = questionDao.getByArchiveType(type)
suspend fun chatWithAi(request: AliyunChatRequest): Response<AliyunChatResponse> = aiApiService.chat(request)
suspend fun chatWithAiStream(request: AliyunChatRequest): okhttp3.ResponseBody = aiApiService.chatStream(request)
suspend fun syncQuestions(token: String): String { val localQuestions = questionDao.getAllForSync() val payload = localQuestions.map { it.toSyncDto() } val response = apiService.syncQuestions( authorization = "Bearer $token", request = SyncQuestionsRequest(questions = payload) )
if (!response.isSuccessful) { throw IllegalStateException("同步失败: ${response.code()}") }
val body = response.body() ?: throw IllegalStateException("同步失败: 空响应") if (!body.success) { throw IllegalStateException(body.message ?: "同步失败") }
body.questions.forEach { remote -> val existing = remote.id?.let { questionDao.getByCloudId(it) } ?: questionDao.getUnsyncedByFingerprint( createTime = remote.createTime, ocrText = remote.ocrText ) val merged = if (existing == null) { remote.toEntity(localId = 0) } else { remote.toEntity(localId = existing.id) } questionDao.insertOrReplace(merged) } return body.message ?: "同步成功（${body.questions.size} 条）" }
private fun QuestionEntity.toSyncDto(): SyncQuestionDto = SyncQuestionDto( id = cloudId, imagePath = imagePath, ocrText = ocrText, aiAnalysis = aiAnalysis, summary = summary.ifBlank { ocrText.take(20) }, subject = subject.ifBlank { "未分类" }, difficulty = difficulty, createTime = createTime, isArchived = isArchived, archiveType = archiveType, deletedAt = deletedAt, updatedAt = updatedAt )
private fun SyncQuestionDto.toEntity(localId: Int): QuestionEntity = QuestionEntity( id = localId, cloudId = id, imagePath = imagePath, ocrText = ocrText, aiAnalysis = aiAnalysis, summary = summary.ifBlank { ocrText.take(20) }, subject = subject.ifBlank { "未分类" }, difficulty = difficulty, createTime = createTime, isArchived = isArchived, archiveType = archiveType, deletedAt = deletedAt, updatedAt = updatedAt ) }

package com.zlearn.data.repository

import com.zlearn.data.database.QuestionDao
import com.zlearn.data.database.QuestionEntity
import com.zlearn.data.remote.ApiService
import com.zlearn.data.remote.SyncQuestionDto
import com.zlearn.data.remote.SyncQuestionsRequest
import com.zlearn.network.AiApiService
import com.zlearn.network.AliyunChatRequest
import com.zlearn.network.AliyunChatResponse
import retrofit2.Response
import javax.inject.Inject

class QuestionRepository @Inject constructor(
    private val questionDao: QuestionDao,
    private val apiService: ApiService,
    private val aiApiService: AiApiService
) {
    suspend fun insert(question: QuestionEntity) = questionDao.insert(question)
    suspend fun getAll(): List<QuestionEntity> = questionDao.getAll()
    suspend fun getById(id: Int): QuestionEntity? = questionDao.getById(id)
    suspend fun update(question: QuestionEntity) = questionDao.update(question)
    suspend fun delete(question: QuestionEntity) {
        val now = System.currentTimeMillis()
        questionDao.softDeleteById(question.id, deletedAt = now, updatedAt = now)
    }
    suspend fun archive(id: Int) = questionDao.archive(id, System.currentTimeMillis())
    suspend fun archive(id: Int, archiveType: String) =
        questionDao.archive(id, archiveType, System.currentTimeMillis())

    suspend fun unarchive(id: Int) = questionDao.unarchive(id, System.currentTimeMillis())
    suspend fun getActive(): List<QuestionEntity> = questionDao.getActive()
    suspend fun getArchived(): List<QuestionEntity> = questionDao.getArchived()
    suspend fun getAllArchiveTypes(): List<String> = questionDao.getAllArchiveTypes()
    suspend fun getByArchiveType(type: String): List<QuestionEntity> = questionDao.getByArchiveType(type)

    suspend fun chatWithAi(request: AliyunChatRequest): Response<AliyunChatResponse> =
        aiApiService.chat(request)

    suspend fun chatWithAiStream(request: AliyunChatRequest): okhttp3.ResponseBody =
        aiApiService.chatStream(request)

    suspend fun getQuestionFromCloud(cloudId: Int): QuestionEntity? {
        val response = apiService.getQuestion(cloudId)
        if (response.isSuccessful) {
            val body = response.body()
            if (body?.success == true && body.question != null) {
                return body.question.toEntity(localId = 0)
            }
        }
        return null
    }

    suspend fun syncQuestions(token: String): String {
        val localQuestions = questionDao.getAllForSync()
        val payload = localQuestions.map { it.toSyncDto() }
        val response = apiService.syncQuestions(
            authorization = "Bearer $token",
            request = SyncQuestionsRequest(questions = payload)
        )

        if (!response.isSuccessful) {
            throw IllegalStateException("同步失败: ${response.code()}")
        }

        val body = response.body() ?: throw IllegalStateException("同步失败: 空响应")
        if (!body.success) {
            throw IllegalStateException(body.message ?: "同步失败")
        }

        body.questions.forEach { remote ->
            val existing = remote.id?.let { questionDao.getByCloudId(it) }
                ?: questionDao.getUnsyncedByFingerprint(
                    createTime = remote.createTime,
                    ocrText = remote.ocrText
                )
            val merged = if (existing == null) {
                remote.toEntity(localId = 0)
            } else {
                remote.toEntity(localId = existing.id)
            }
            questionDao.insertOrReplace(merged)
        }
        return body.message ?: "同步成功（${body.questions.size} 条）"
    }

    private fun QuestionEntity.toSyncDto(): SyncQuestionDto = SyncQuestionDto(
        id = cloudId,
        imagePath = imagePath,
        ocrText = ocrText,
        aiAnalysis = aiAnalysis,
        summary = summary.ifBlank { ocrText.take(20) },
        subject = subject.ifBlank { "未分类" },
        difficulty = difficulty,
        createTime = createTime,
        isArchived = isArchived,
        archiveType = archiveType,
        deletedAt = deletedAt,
        updatedAt = updatedAt
    )

    private fun SyncQuestionDto.toEntity(localId: Int): QuestionEntity = QuestionEntity(
        id = localId,
        cloudId = id,
        imagePath = imagePath,
        ocrText = ocrText,
        aiAnalysis = aiAnalysis,
        summary = summary.ifBlank { ocrText.take(20) },
        subject = subject.ifBlank { "未分类" },
        difficulty = difficulty,
        createTime = createTime,
        isArchived = isArchived,
        archiveType = archiveType,
        deletedAt = deletedAt,
        updatedAt = updatedAt
    )
}

package com.zlearn.ui.question.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.zlearn.domain.usecase.QuestionUseCases
import com.zlearn.data.database.QuestionEntity
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject
import io.reactivex.rxjava3.disposables.CompositeDisposable
import okhttp3.*
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject

@HiltViewModel
class QuestionViewModel @Inject constructor(
    private val useCases: QuestionUseCases
) : ViewModel() {
    private val disposables = CompositeDisposable()
    private val _questions = MutableStateFlow<List<QuestionEntity>>(emptyList())
    val questions: StateFlow<List<QuestionEntity>> = _questions.asStateFlow()

    private val _aiResponse = MutableStateFlow<String?>(null)
    val aiResponse: StateFlow<String?> = _aiResponse.asStateFlow()

    private val _aiStreamResponse = MutableStateFlow("")
    val aiStreamResponse: StateFlow<String> = _aiStreamResponse.asStateFlow()

    init {
        loadQuestions()
    }

    fun loadQuestions() {
        viewModelScope.launch {
            _questions.value = useCases.getActiveQuestions()
        }
    }

    fun addQuestion(question: QuestionEntity) {
        viewModelScope.launch {
            useCases.addQuestion(question)
            loadQuestions()
        }
    }

    fun deleteQuestion(question: QuestionEntity) {
        viewModelScope.launch {
            useCases.deleteQuestion(question)
            loadQuestions()
        }
    }

    fun archiveQuestion(id: Int) {
        viewModelScope.launch {
            useCases.archiveQuestion(id)
            loadQuestions()
        }
    }

    fun chatWithAi(message: String) {
        viewModelScope.launch {
            val request = com.zlearn.network.AliyunChatRequest(
                model = "qwen-turbo",
                input = com.zlearn.network.Input(
                    messages = listOf(com.zlearn.network.Message(role = "user", content = message))
                )
            )
            val response = useCases.chatWithAi(request)
            if (response.isSuccessful) {
                _aiResponse.value = response.body()?.output?.text
            } else {
                _aiResponse.value = "AI请求失败: ${response.code()}"
            }
        }
    }

    // 独立的summary生成方法，不影响主界面AI对话
    suspend fun generateSummary(ocrText: String): String {
        val request = com.zlearn.network.AliyunChatRequest(
            model = "qwen-turbo",
            input = com.zlearn.network.Input(
                messages = listOf(
                    com.zlearn.network.Message(role = "user", content = "请用20字以内总结这段内容：$ocrText")
                )
            )
        )
        val response = useCases.chatWithAi(request)
        return if (response.isSuccessful) {
            response.body()?.output?.text ?: ""
        } else {
            ""
        }
    }

    fun updateAiAnalysis(id: Int, newAnalysis: String) {
        viewModelScope.launch {
            val question = useCases.getQuestionById(id)
            if (question != null) {
                useCases.updateQuestion(question.copy(aiAnalysis = newAnalysis))
                loadQuestions()
            }
        }
    }

    fun clearAiStreamResponse() {
        _aiStreamResponse.value = ""
    }
    private val _isLoading = mutableStateOf(false)
    val isLoading: Boolean get() = _isLoading.value

    suspend fun chatWithAiStream(prompt: String) {
        _isLoading.value = true
        // ... 流式调用逻辑
        _isLoading.value = false
    }
    // 真正流式：DashScope API (OkHttp SSE)
    fun chatWithAiStream(message: String) {
        _aiStreamResponse.value = ""
        viewModelScope.launch {
            val request = com.zlearn.network.AliyunChatRequest(
                model = "qwen-plus",
                input = com.zlearn.network.Input(
                    messages = listOf(com.zlearn.network.Message(role = "user", content = message))
                )
            )
            withContext(Dispatchers.IO) {
                var responseBody: ResponseBody? = null
                try {
                    responseBody = useCases.chatWithAiStream(request)
                    val source = responseBody.source()
                    while (true) {
                        val line = source.readUtf8Line() ?: break
                        if (line.startsWith("data:")) {
                            val json = line.removePrefix("data:").trim()
                            if (json.isNotBlank() && json != "[DONE]") {
                                val obj = JSONObject(json)
                                val content = obj.optJSONObject("output")
                                    ?.optString("text") ?: ""
                                if (content.isNotBlank()) {
                                    withContext(Dispatchers.Main) {
                                        _aiStreamResponse.value = content
                                    }
                                }
                            }
                        }
                    }
                } catch (e: Exception) {
                    withContext(Dispatchers.Main) {
                        _aiStreamResponse.value += "\n[流式AI出错: ${e.message}]"
                    }
                } finally {
                    responseBody?.close()
                }
            }
        }
    }

    override fun onCleared() {
        super.onCleared()
        disposables.clear()
    }
}

package com.zlearn.ui.question.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.zlearn.domain.usecase.QuestionUseCases
import com.zlearn.data.database.QuestionEntity
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject
import io.reactivex.rxjava3.disposables.CompositeDisposable
import okhttp3.*
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.getValue
import androidx.compose.runtime.setValue

@HiltViewModel
class QuestionViewModel @Inject constructor(
    private val useCases: QuestionUseCases
) : ViewModel() {
    private val disposables = CompositeDisposable()
    private val _questions = MutableStateFlow<List<QuestionEntity>>(emptyList())
    val questions: StateFlow<List<QuestionEntity>> = _questions.asStateFlow()

    private val _aiResponse = MutableStateFlow<String?>(null)
    val aiResponse: StateFlow<String?> = _aiResponse.asStateFlow()

    private val _aiStreamResponse = MutableStateFlow("")
    val aiStreamResponse: StateFlow<String> = _aiStreamResponse.asStateFlow()

    private val _isLoading = mutableStateOf(false)
    val isLoading: Boolean get() = _isLoading.value

    init {
        loadQuestions()
    }

    fun loadQuestions() {
        viewModelScope.launch {
            _questions.value = useCases.getActiveQuestions()
        }
    }

    fun addQuestion(question: QuestionEntity) {
        viewModelScope.launch {
            useCases.addQuestion(question)
            loadQuestions()
        }
    }

    fun deleteQuestion(question: QuestionEntity) {
        viewModelScope.launch {
            useCases.deleteQuestion(question)
            loadQuestions()
        }
    }

    fun archiveQuestion(id: Int) {
        viewModelScope.launch {
            useCases.archiveQuestion(id)
            loadQuestions()
        }
    }

    fun chatWithAi(message: String) {
        viewModelScope.launch {
            val request = com.zlearn.network.AliyunChatRequest(
                model = "qwen-turbo",
                input = com.zlearn.network.Input(
                    messages = listOf(com.zlearn.network.Message(role = "user", content = message))
                )
            )
            val response = useCases.chatWithAi(request)
            if (response.isSuccessful) {
                _aiResponse.value = response.body()?.output?.text
            } else {
                _aiResponse.value = "AI请求失败: ${response.code()}"
            }
        }
    }

    // 独立的summary生成方法，不影响主界面AI对话
    suspend fun generateSummary(ocrText: String): String {
        val request = com.zlearn.network.AliyunChatRequest(
            model = "qwen-turbo",
            input = com.zlearn.network.Input(
                messages = listOf(
                    com.zlearn.network.Message(role = "user", content = "请用20字以内总结这段内容：$ocrText")
                )
            )
        )
        val response = useCases.chatWithAi(request)
        return if (response.isSuccessful) {
            response.body()?.output?.text ?: ""
        } else {
            ""
        }
    }

    fun updateAiAnalysis(id: Int, newAnalysis: String) {
        viewModelScope.launch {
            val question = useCases.getQuestionById(id)
            if (question != null) {
                useCases.updateQuestion(question.copy(aiAnalysis = newAnalysis))
                loadQuestions()
            }
        }
    }

    fun clearAiStreamResponse() {
        _aiStreamResponse.value = ""
    }

    // 真正流式：DashScope API (OkHttp SSE)
    fun chatWithAiStream(message: String) {
        _aiStreamResponse.value = ""
        viewModelScope.launch {
            val request = com.zlearn.network.AliyunChatRequest(
                model = "qwen-plus",
                input = com.zlearn.network.Input(
                    messages = listOf(com.zlearn.network.Message(role = "user", content = message))
                )
            )
            withContext(Dispatchers.IO) {
                var responseBody: ResponseBody? = null
                try {
                    responseBody = useCases.chatWithAiStream(request)
                    val source = responseBody.source()
                    while (true) {
                        val line = source.readUtf8Line() ?: break
                        if (line.startsWith("data:")) {
                            val json = line.removePrefix("data:").trim()
                            if (json.isNotBlank() && json != "[DONE]") {
                                val obj = JSONObject(json)
                                val content = obj.optJSONObject("output")
                                    ?.optString("text") ?: ""
                                if (content.isNotBlank()) {
                                    withContext(Dispatchers.Main) {
                                        _aiStreamResponse.value = content
                                    }
                                }
                            }
                        }
                    }
                } catch (e: Exception) {
                    withContext(Dispatchers.Main) {
                        _aiStreamResponse.value += "\n[流式AI出错: ${e.message}]"
                    }
                } finally {
                    responseBody?.close()
                }
            }
        }
    }

    // 替换原chatWithAiStream为suspend版本，支持loading
    suspend fun chatWithAiStream(prompt: String) {
        _isLoading.value = true
        try {
            _aiStreamResponse.value = ""
            val request = com.zlearn.network.AliyunChatRequest(
                model = "qwen-plus",
                input = com.zlearn.network.Input(
                    messages = listOf(com.zlearn.network.Message(role = "user", content = prompt))
                )
            )
            withContext(Dispatchers.IO) {
                var responseBody: ResponseBody? = null
                try {
                    responseBody = useCases.chatWithAiStream(request)
                    val source = responseBody.source()
                    while (true) {
                        val line = source.readUtf8Line() ?: break
                        if (line.startsWith("data:")) {
                            val json = line.removePrefix("data:").trim()
                            if (json.isNotBlank() && json != "[DONE]") {
                                val obj = JSONObject(json)
                                val content = obj.optJSONObject("output")
                                    ?.optString("text") ?: ""
                                if (content.isNotBlank()) {
                                    withContext(Dispatchers.Main) {
                                        _aiStreamResponse.value = content
                                    }
                                }
                            }
                        }
                    }
                } catch (e: Exception) {
                    withContext(Dispatchers.Main) {
                        _aiStreamResponse.value += "\n[流式AI出错: ${e.message}]"
                    }
                } finally {
                    responseBody?.close()
                }
            }
        } finally {
            _isLoading.value = false
        }
    }

    override fun onCleared() {
        super.onCleared()
        disposables.clear()
    }
}

package com.zlearn.ui

import android.app.Activity
import android.content.Intent
import android.widget.Toast
