package com.zlearn.ui.theme
import android.app.Activity import android.os.Build import androidx.compose.foundation.isSystemInDarkTheme import androidx.compose.material3.MaterialTheme import androidx.compose.material3.darkColorScheme import androidx.compose.material3.dynamicDarkColorScheme import androidx.compose.material3.dynamicLightColorScheme import androidx.compose.material3.lightColorScheme import androidx.compose.runtime.Composable import androidx.compose.ui.graphics.Color import androidx.compose.ui.platform.LocalContext
private val DarkColorScheme = darkColorScheme( primary = DeepBlue, secondary = DeepBlue, background = LightYellow, surface = CardWhite, onPrimary = Color.White, onSecondary = Color.White, onBackground = Color(0xFF1C1B1F), onSurface = Color(0xFF1C1B1F) )
private val LightColorScheme = lightColorScheme( primary = DeepBlue, secondary = DeepBlue, background = LightYellow, surface = CardWhite, onPrimary = Color.White, onSecondary = Color.White, onBackground = Color(0xFF1C1B1F), onSurface = Color(0xFF1C1B1F) )
@Composable fun MyApplicationTheme( darkTheme: Boolean = isSystemInDarkTheme(), // Dynamic color is available on Android 12+ dynamicColor: Boolean = true, content: @Composable () -> Unit ) { val colorScheme = when { dynamicColor && Build.VERSION.SDK_INT >= Build.VERSION_CODES.S -> { val context = LocalContext.current if (darkTheme) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context) }
darkTheme -> DarkColorScheme else -> LightColorScheme }
MaterialTheme( colorScheme = colorScheme, typography = Typography, content = content ) }

