private val DarkColorScheme = darkColorScheme( primary = DeepBlue, secondary = DeepBlue, background = LightYellow, surface = CardWhite, onPrimary = Color.White, onSecondary = Color.White, onBackground = Color(0xFF1C1B1F), onSurface = Color(0xFF1C1B1F) )
