package com.zlearn.ui.question.screens

import androidx.compose.runtime.Composable

// 可复用的流光边框输入框组件
@Composable
fun FlowingBorderTextField(
    value: String,
    onValueChange: (String) -> Unit,
    label: String,
    modifier: Modifier = Modifier,
    isActive: Boolean = true  // 是否激活流光效果
) {
    val infiniteTransition = rememberInfiniteTransition(label = "flow")
    val gradientOffset by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(2500, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "offset"
    )

    Box(modifier = modifier) {
        // 流光边框
        if (isActive && value.isNotEmpty()) {
            Box(
                modifier = Modifier
                    .matchParentSize()
                    .clip(RoundedCornerShape(28.dp))
                    .drawBehind {
                        val strokeWidth = 1.5.dp.toPx()
                        val colors = listOf(
                            Color(0xFF6366F1),  // Indigo
                            Color(0xFF8B5CF6),  // Purple
                            Color(0xFFEC4899),  // Pink
                            Color(0xFF6366F1)   // Back to Indigo
                        )
                        val gradient = Brush.linearGradient(
                            colors = colors,
                            start = Offset(x = size.width * gradientOffset, y = 0f),
                            end = Offset(x = size.width * (gradientOffset - 0.3f), y = size.height)
                        )
                        drawRoundRect(
                            brush = gradient,
                            style = Stroke(width = strokeWidth),
                            cornerRadius = CornerRadius(28.dp.toPx())
                        )
                    }
            )
        }

        OutlinedTextField(
            value = value,
            onValueChange = onValueChange,
            label = { Text(label) },
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(28.dp),
            colors = OutlinedTextFieldDefaults.colors(
                focusedBorderColor = if (value.isNotEmpty()) Color.Transparent else MaterialTheme.colorScheme.primary,
                unfocusedBorderColor = Color.Transparent
            )
        )
    }
}

package com.zlearn.ui.question.screens
import androidx.compose.animation.core.LinearEasing import androidx.compose.animation.core.RepeatMode import androidx.compose.animation.core.animateFloat import androidx.compose.animation.core.infiniteRepeatable import androidx.compose.animation.core.rememberInfiniteTransition import androidx.compose.animation.core.tween import androidx.compose.foundation.layout.Box import androidx.compose.foundation.text.OutlinedTextField import androidx.compose.material3.MaterialTheme import androidx.compose.material3.OutlinedTextFieldDefaults import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.runtime.getValue import androidx.compose.ui.Modifier import androidx.compose.ui.draw.clip import androidx.compose.ui.draw.drawBehind import androidx.compose.ui.geometry.CornerRadius import androidx.compose.ui.geometry.Offset import androidx.compose.ui.graphics.Brush import androidx.compose.ui.graphics.Color import androidx.compose.ui.graphics.Stroke import androidx.compose.ui.unit.dp
// 可复用的流光边框输入框组件 @Composable fun FlowingBorderTextField( value: String, onValueChange: (String) -> Unit, label: String, modifier: Modifier = Modifier, isActive: Boolean = true // 是否激活流光效果 ) { val infiniteTransition = rememberInfiniteTransition(label = "flow") val gradientOffset by infiniteTransition.animateFloat( initialValue = 0f, targetValue = 1f, animationSpec = infiniteRepeatable( animation = tween(2500, easing = LinearEasing), repeatMode = RepeatMode.Restart ), label = "offset" )
Box(modifier = modifier) { // 流光边框 if (isActive && value.isNotEmpty()) { Box( modifier = Modifier .matchParentSize() .clip(RoundedCornerShape(28.dp)) .drawBehind { val strokeWidth = 1.5.dp.toPx() val colors = listOf( Color(0xFF6366F1), // Indigo Color(0xFF8B5CF6), // Purple Color(0xFFEC4899), // Pink Color(0xFF6366F1) // Back to Indigo ) val gradient = Brush.linearGradient( colors = colors, start = Offset(x = size.width * gradientOffset, y = 0f), end = Offset(x = size.width * (gradientOffset - 0.3f), y = size.height) ) drawRoundRect( brush = gradient, style = Stroke(width = strokeWidth), cornerRadius = CornerRadius(28.dp.toPx()) ) } ) }
OutlinedTextField( value = value, onValueChange = onValueChange, label = { Text(label) }, modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(28.dp), colors = OutlinedTextFieldDefaults.colors( focusedBorderColor = if (value.isNotEmpty()) Color.Transparent else MaterialTheme.colorScheme.primary, unfocusedBorderColor = Color.Transparent ) ) } }

